/*
 * A003842  The infinite Fibonacci word: start with 1, repeatedly apply the
 *          morphism 1->12, 2->1, take limit; or, start with S(0)=2, S(1)=1,
 *          and for n>1 define S(n)=S(n-1)S(n-2), then the sequence is S(oo).
 * https://oeis.org/A003842
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, nice, easy
 * Formula:   a(n) is the n-th element of the Fibonacci word generated by
 *            S(0)=2, S(1)=1, S(n)=S(n-1)S(n-2)
 * Range:     u8 n <= 9527, u16 n <= 9527, u32 n <= 9527, u64 n <= 9527,
 *            u128 n <= 9527, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n) {
    // Compute lengths of S(k) until one exceeds n
    uint64_t lengths[100];
    lengths[0] = 1;
    lengths[1] = 1;
    int max_k = 1;
    
    while (lengths[max_k] <= n) {
        max_k++;
        lengths[max_k] = lengths[max_k - 1] + lengths[max_k - 2];
    }
    
    // Decompose n using the Fibonacci structure: S(k) = S(k-1) S(k-2)
    int k = max_k;
    idx_t pos = n;
    
    while (k > 1) {
        uint64_t len_k_minus_1 = lengths[k - 1];
        if (pos < len_k_minus_1) {
            k = k - 1;
        } else {
            pos -= len_k_minus_1;
            k = k - 2;
        }
    }
    
    // Base cases: S(0)=[2], S(1)=[1]
    return (seq_t)(k == 0 ? 2 : 1);
}
